"""Freeze complete actual inactive technical artifacts, never review outcomes."""
import hashlib,json,subprocess
from datetime import datetime,timezone
from pathlib import Path
ROOT=Path.cwd();OWN=Path(__file__).resolve().parent;REL=OWN.relative_to(ROOT).as_posix()
def data(p):return json.loads(p.read_text())
def bind(p):
 b=p.read_bytes();return {'path':p.relative_to(ROOT).as_posix(),'sha256':'sha256:'+hashlib.sha256(b).hexdigest(),'bytes':len(b)}
def write(path,value):
 assert not path.exists(),str(path);path.write_text(json.dumps(value,ensure_ascii=False,indent=2)+'\n')
freeze=OWN/'sixteen-native-technical-author.first.freeze.json';assert not freeze.exists(),'Do not alter sealed preparation.'
entrypath=OWN/'neutral-sixteen-native-independent-review.entry.json';entry=data(entrypath)
checks=['checks/ordinary-capsule-public-loader.actual.json','checks/ordinary-native-campaign-bundle-and-whole-page-check.actual.json','checks/ordinary-capsule-positive-json-schema-portability.actual-terminal.json','checks/four-genuine-native-originals.git-index-bytes.actual.json']
for c in checks:
 r=data(OWN/c);assert r.get('exitCode',0)==0
paths=sorted(set([b['path'] for b in entry['inputBindings']]+[p.relative_to(ROOT).as_posix() for p in OWN.rglob('*') if p.is_file()]))
for p in paths:assert (ROOT/p).is_file() and not (ROOT/p).is_symlink(),p
ignore=subprocess.run(['git','check-ignore','--stdin'],input='\n'.join(paths)+'\n',text=True,capture_output=True);assert ignore.returncode==1 and ignore.stdout=='',ignore.stdout
write(OWN/'checks/all-required-inputs-and-own-outputs.portability.actual.json',{'schemaVersion':1,'role':'ordinary Git discoverability and actual files; no scientific review','checkedPathCount':len(paths),'ordinaryCheckIgnoreExitCode':ignore.returncode,'ignoredRequiredPaths':[],'symlinksWithinNewTechnicalPacket':0,'nativeOriginalsIndexProofPath':REL+'/checks/four-genuine-native-originals.git-index-bytes.actual.json','ignoreOrValidatorChanges':False,'exitCode':0})
write(OWN/'checks/unsealed-attempt-contract-remediation.actual.json',{'schemaVersion':1,'role':'technical attempt history only','retainedUnsealedFirstAttemptPath':REL+'/source-atlas/atlas.inputs.inactive.json','firstAttemptResult':'ordinary pure compiler rejected non-book-local output paths before any atlas writes','normalContractPreserved':True,'operativeInputPath':REL+'/source-atlas/atlas.inputs.book-local-v2.inactive.json','ordinaryCompilerOutputArchiveMapPath':REL+'/source-atlas/book-local-output-paths.actual.json','ordinaryCompilerOutputsInstalledOnlyUnderTmp':True,'firstAttemptQAPath':REL+'/candidate/visualization-qa.current392.sixteen-unapproved.inactive.json','ordinaryPublicPathQAPath':entry['candidateVisualizationQAPath'],'publicPathRepair':'app/public plus exact root-relative imageUrl, actual image bytes copied to tmp and bound in portable aliases','liveAppWrites':0,'scientificReviewClaim':False})
entry.update({'actualCurrentBaselineCanonicalGoals':476,'actualCurrentBaselineAtomicGoals':392,'activeStrictBaseline':{'biologieStrictCompletedGoals':244,'currentCurricularAtomicGoals':392,'source':'Root complete central report supplied; this preparation runs only affected technical checks'},'offlineAnalogDigitalTaskMediaManifestPath':entry['originalCaseAuthorEntry']['path'].rsplit('/',1)[0]+'/analog-digital-media.author-manifest.json','ordinarySourceAtlasOutputArchiveMapPath':REL+'/source-atlas/book-local-output-paths.actual.json','ordinaryTechnicalChecks':[bind(OWN/c) for c in checks]+[bind(OWN/'checks/all-required-inputs-and-own-outputs.portability.actual.json')],'firstFreezePath':REL+'/'+freeze.name,'requiredNextReviews':['two genuine independent whole native D/P reviews, including current original-source roles, whole16DEEN descriptions,32 substantial DEEN cases and current page/context/image inputs','actual raster original/360/680 scientific and visual approvals for all16 target contexts, including seven kept PNGs with new target bindings','resolution of actual independent findings before approved P/D/V adoption','Root guarded integration with current protected A/M, retained376 page bindings and full central plus dependent Layer-A checks at a stable integration state'],'currentPStatusCounts':{'approved':0,'needs_human_review':16,'rejected':0},'newScientificClosures':0,'restoredActiveBindings':0,'predictedNetStrictGainAfterActualApprovalAndIntegration':16,'predictionIsActualClosure':False,'whole16ExistingAandM':'exact unchanged decisions retained; no independent or new author review claimed','technicalBlockers':[],'independentReviewBlockers':'unknown until genuine first verdicts','gitStagingScope':'only four explicitly authorized actual native originals; no commit or push'})
entrypath.write_text(json.dumps(entry,ensure_ascii=False,indent=2)+'\n')
files=[bind(p) for p in sorted(OWN.rglob('*')) if p.is_file() and p!=freeze]
write(freeze,{'schemaVersion':1,'role':'first immutable complete author technical preparation, not an independent review','createdAt':datetime.now(timezone.utc).isoformat(),'entry':bind(entrypath),'fileCount':len(files),'files':files,'actualScientificIndependentResults':0,'actualHumanReviews':0,'activeWrites':[],'actualStrictGain':0,'actualNewScientificClosures':0,'actualRestoredBindings':0})
for b in data(freeze)['files']:assert bind(ROOT/b['path'])==b
print(json.dumps({'neutralEntry':bind(entrypath),'firstFreeze':bind(freeze),'fileCount':len(files),'actualNativeGoals':16,'cases':32,'technicalBlockers':0,'scientificIndependentResults':0,'strictGain':0}))
